from collections import deque

def get_neighbors(r, c, grid):
    nr, nc = len(grid), len(grid[0]) if grid else 0
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr2, nc2 = r+dr, c+dc
        if 0 <= nr2 < nr and 0 <= nc2 < len(grid[0]) and grid[nr2][nc2] == 5:
            yield (nr2, nc2)

def check_connected(grid, color):
    """Check if all cells of a certain color are in the same connected component"""
    if not grid:
        return True
    start = None
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                start = (r, c)
                break
        if start:
            break

    if not start:
        return True

    visited = set()
    queue = deque([start])
    visited.add(start)

    while queue:
        r, c = queue.popleft()
        for nr, nc in get_neighbors(r, c, grid):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

    # Check if all cells of this color are in the connected component
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r, c) not in visited:
                return False
    return True

