# Count components
def count_components(grid, color):
    if not grid:
        return 0
    visited = set()
    count = 0

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r, c) not in visited:
                count += 1
                queue = deque([(r, c)])
                visited.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    for nr, nc in get_neighbors(cr, cc, grid):
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
    return count

print("Number of connected components of 5 in demo:", count_components(input_demo, 5))

